{
  "name": "台式数字万用表",
  "name_en": "Bench Digital Multimeter",
  "manufacturer": "Agilent Technologies",
  "description": "这是一款安捷伦 34410A 系列 6.5 位台式数字万用表，用于实验室中的高精度电学测量，如电压、电流、电阻等参数测试。该类仪器常用于台架测试、自动化测量以及带内部读数存储的采样记录场景。",
  "description_en": "This is an Agilent 34410A-series 6.5-digit bench digital multimeter used for precise electrical measurements in laboratories, such as voltage, current, and resistance. Instruments in this class are commonly used for bench testing, automated measurement setups, and buffered data acquisition with internal reading memory.",
  "tag_hints": [
    "6.5-digit DMM",
    "bench digital multimeter",
    "voltage current resistance measurement",
    "electrical test and measurement",
    "buffered reading memory",
    "automated lab measurements"
  ],
  "actions": [
    {
      "action_name": "auto-abort",
      "description": "中止当前正在进行的所有测量。",
      "description_en": "Abort all measurements currently in progress."
    },
    {
      "action_name": "auto-clear_memory",
      "description": "清除仪器的非易失性存储器中的读数数据。",
      "description_en": "Clear readings stored in the instrument's non-volatile memory."
    },
    {
      "action_name": "auto-fetch",
      "description": "将仪器读数存储器中的测量结果传送到输出缓冲区并输出。",
      "description_en": "Transfer measurement readings from the instrument memory to the output buffer for output."
    },
    {
      "action_name": "auto-init",
      "description": "启动测量流程，使仪器进入等待触发的状态。",
      "description_en": "Initiate the measurement sequence and place the instrument in a wait-for-trigger state."
    },
    {
      "action_name": "auto-r",
      "description": "执行指定次数的测量，并以二进制方式传输出测量数据。",
      "description_en": "Perform a specified number of measurements and transfer the data using a binary format."
    },
    {
      "action_name": "auto-read_data",
      "description": "从读数存储器中读取指定数量的数据点。",
      "description_en": "Read a specified number of data points from reading memory."
    },
    {
      "action_name": "auto-read_data_nvmem",
      "description": "读取非易失性存储器中的全部测量读数。",
      "description_en": "Read all measurement readings stored in non-volatile memory."
    },
    {
      "action_name": "auto-read_last_data",
      "description": "读取最近一次测得的读数。",
      "description_en": "Read the most recent measurement value."
    },
    {
      "action_name": "auto-read_meter",
      "description": "触发一次测量流程，并在满足触发条件后将读数输出。",
      "description_en": "Start a measurement sequence and output the reading once the trigger condition is met."
    },
    {
      "action_name": "auto-data_point_count",
      "description": "获取读数存储器中的数据点总数。",
      "description_en": "Get the total number of readings stored in reading memory."
    }
  ]
}

